def lin_fit(g, degT=3, degG=1):
    cols=[]
    for i in range(degT+1):
        for j in range(degG+1):
            cols.append((T**i)*(g**j))
    A=np.array(cols).T
    c,res,_,_=np.linalg.lstsq(A,sigma,rcond=None)
    r=A@c-sigma
    return np.mean(r**2)/np.var(sigma), c
